دالة أطول_كلمة(نص) {
    متغير كلمات = فصل(نص، " ")
    متغير أطول = ٠
    متغير نتيجة = ""
    من_أجل (كلمة في كلمات) {
        إذا (طول(كلمة) > أطول) {
            أطول = طول(كلمة)
            نتيجة = كلمة
        } وإلا إذا (طول(كلمة) == أطول) {
            نتيجة = نص(نتيجة، " ") + كلمة
        }
    }
    ارجع نتيجة
}
```

